using ModelContextProtocol.Server;
using System.ComponentModel;
using System.Net.Http.Json;
using System.Text.Json.Serialization;

namespace McpServer;

/// <summary>
/// MCP tools are discovered by the SDK via [McpServerToolType] on the class
/// and [McpServerTool] on each method. The SDK instantiates this class per-call
/// and injects constructor dependencies from the DI container.
/// </summary>
[McpServerToolType]
public class WeatherTools
{
    private readonly HttpClient _httpClient;

    // Constructor injection — the SDK resolves HttpClient from DI automatically.
    public WeatherTools(HttpClient httpClient)
    {
        _httpClient = httpClient;
    }

    [McpServerTool, Description("Get current weather for a city.")]
    public async Task<string> GetWeather(
        [Description("City name, e.g. 'London'")] string city)
    {
        // Using Open-Meteo geocoding + forecast (no API key needed)
        var geo = await _httpClient.GetFromJsonAsync<GeoResponse>(
            $"https://geocoding-api.open-meteo.com/v1/search?name={Uri.EscapeDataString(city)}&count=1");

        if (geo?.Results is not { Length: > 0 })
            return $"City '{city}' not found.";

        var loc = geo.Results[0];
        var weather = await _httpClient.GetFromJsonAsync<WeatherResponse>(
            $"https://api.open-meteo.com/v1/forecast?latitude={loc.Latitude}&longitude={loc.Longitude}&current_weather=true");

        if (weather?.CurrentWeather is null)
            return "Weather data unavailable.";

        var w = weather.CurrentWeather;
        return $"Weather in {loc.Name}: {w.Temperature}°C, wind {w.WindSpeed} km/h";
    }

    [McpServerTool, Description("Get the forecast high/low for the next N days.")]
    public async Task<string> GetForecast(
        [Description("City name")] string city,
        [Description("Number of forecast days (1-7)")] int days = 3)
    {
        days = Math.Clamp(days, 1, 7);

        var geo = await _httpClient.GetFromJsonAsync<GeoResponse>(
            $"https://geocoding-api.open-meteo.com/v1/search?name={Uri.EscapeDataString(city)}&count=1");

        if (geo?.Results is not { Length: > 0 })
            return $"City '{city}' not found.";

        var loc = geo.Results[0];
        var url = $"https://api.open-meteo.com/v1/forecast?latitude={loc.Latitude}&longitude={loc.Longitude}" +
                  $"&daily=temperature_2m_max,temperature_2m_min&forecast_days={days}";

        var forecast = await _httpClient.GetFromJsonAsync<ForecastResponse>(url);
        if (forecast?.Daily is null)
            return "Forecast data unavailable.";

        var lines = new List<string> { $"Forecast for {loc.Name}:" };
        for (int i = 0; i < forecast.Daily.Time.Length; i++)
        {
            lines.Add($"  {forecast.Daily.Time[i]}: " +
                      $"High {forecast.Daily.TemperatureMax[i]}°C, " +
                      $"Low {forecast.Daily.TemperatureMin[i]}°C");
        }
        return string.Join("\n", lines);
    }
}

// --- JSON models for Open-Meteo API ---

public record GeoResponse(
    [property: JsonPropertyName("results")] GeoResult[]? Results);

public record GeoResult(
    [property: JsonPropertyName("name")] string Name,
    [property: JsonPropertyName("latitude")] double Latitude,
    [property: JsonPropertyName("longitude")] double Longitude);

public record WeatherResponse(
    [property: JsonPropertyName("current_weather")] CurrentWeather? CurrentWeather);

public record CurrentWeather(
    [property: JsonPropertyName("temperature")] double Temperature,
    [property: JsonPropertyName("windspeed")] double WindSpeed);

public record ForecastResponse(
    [property: JsonPropertyName("daily")] DailyForecast? Daily);

public record DailyForecast(
    [property: JsonPropertyName("time")] string[] Time,
    [property: JsonPropertyName("temperature_2m_max")] double[] TemperatureMax,
    [property: JsonPropertyName("temperature_2m_min")] double[] TemperatureMin);

